#include <stdio.h>
#include <stdlib.h>

#define MAXG 30

typedef struct {
    long long ans;
    int pref_g[MAXG], pref_c[MAXG], pref_len;
    int suff_g[MAXG], suff_c[MAXG], suff_len;
    int g;
    int left, right;
} Node;

Node tree[200005];
int node_cnt = 0;
int S[100005];

int gcd(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

void init_leaf(Node *node, int val) {
    node->ans = (val > 1) ? 1 : 0;
    node->pref_len = 1;
    node->pref_g[0] = val;
    node->pref_c[0] = 1;
    node->suff_len = 1;
    node->suff_g[0] = val;
    node->suff_c[0] = 1;
    node->g = val;
    node->left = node->right = -1;
}

void merge(Node *res, const Node *L, const Node *R) {
    res->ans = L->ans + R->ans;
    // cross
    for (int i = 0; i < L->suff_len; i++) {
        int g1 = L->suff_g[i];
        if (g1 == 1) break;
        int c1 = L->suff_c[i];
        for (int j = 0; j < R->pref_len; j++) {
            int g2 = R->pref_g[j];
            if (g2 == 1) break;
            if (gcd(g1, g2) > 1) {
                res->ans += (long long)c1 * R->pref_c[j];
            }
        }
    }
    // new pref
    res->pref_len = 0;
    for (int i = 0; i < L->pref_len; i++) {
        res->pref_g[res->pref_len] = L->pref_g[i];
        res->pref_c[res->pref_len] = L->pref_c[i];
        res->pref_len++;
    }
    int gL = L->g;
    for (int i = 0; i < R->pref_len; i++) {
        int g2 = R->pref_g[i];
        int new_g = gcd(gL, g2);
        int c2 = R->pref_c[i];
        if (res->pref_len > 0 && res->pref_g[res->pref_len-1] == new_g) {
            res->pref_c[res->pref_len-1] += c2;
        } else {
            res->pref_g[res->pref_len] = new_g;
            res->pref_c[res->pref_len] = c2;
            res->pref_len++;
        }
    }
    // new suff
    res->suff_len = 0;
    for (int i = 0; i < R->suff_len; i++) {
        res->suff_g[res->suff_len] = R->suff_g[i];
        res->suff_c[res->suff_len] = R->suff_c[i];
        res->suff_len++;
    }
    int gR = R->g;
    for (int i = 0; i < L->suff_len; i++) {
        int g1 = L->suff_g[i];
        int new_g = gcd(g1, gR);
        int c1 = L->suff_c[i];
        if (res->suff_len > 0 && res->suff_g[res->suff_len-1] == new_g) {
            res->suff_c[res->suff_len-1] += c1;
        } else {
            res->suff_g[res->suff_len] = new_g;
            res->suff_c[res->suff_len] = c1;
            res->suff_len++;
        }
    }
    res->g = gcd(L->g, R->g);
    res->left = res->right = -1;
}

int build(int l, int r) {
    int idx = node_cnt++;
    if (l == r) {
        init_leaf(&tree[idx], S[l]);
        return idx;
    }
    int mid = (l + r) / 2;
    int left = build(l, mid);
    int right = build(mid+1, r);
    tree[idx].left = left;
    tree[idx].right = right;
    merge(&tree[idx], &tree[left], &tree[right]);
    return idx;
}

void update(int idx, int l, int r, int pos, int val) {
    if (l == r) {
        init_leaf(&tree[idx], val);
        return;
    }
    int mid = (l + r) / 2;
    if (pos <= mid) {
        update(tree[idx].left, l, mid, pos, val);
    } else {
        update(tree[idx].right, mid+1, r, pos, val);
    }
    merge(&tree[idx], &tree[tree[idx].left], &tree[tree[idx].right]);
}

void query(int idx, int l, int r, int ql, int qr, Node *res) {
    if (ql <= l && r <= qr) {
        *res = tree[idx];
        return;
    }
    int mid = (l + r) / 2;
    if (qr <= mid) {
        query(tree[idx].left, l, mid, ql, qr, res);
    } else if (ql > mid) {
        query(tree[idx].right, mid+1, r, ql, qr, res);
    } else {
        Node left, right;
        query(tree[idx].left, l, mid, ql, qr, &left);
        query(tree[idx].right, mid+1, r, ql, qr, &right);
        merge(res, &left, &right);
    }
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);
    for (int i = 1; i <= N; i++) {
        scanf("%d", &S[i]);
    }
    node_cnt = 0;
    int root = build(1, N);
    for (int i = 0; i < M; i++) {
        int T, A, B;
        scanf("%d %d %d", &T, &A, &B);
        if (T == 1) {
            update(root, 1, N, A, B);
        } else {
            Node res;
            query(root, 1, N, A, B, &res);
            printf("%lld\n", res.ans);
        }
    }
    return 0;
}
